('mathl1f_001', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 9x + 4 = 49, what is the value of x?', '["6", "5", "53/9", "45"]'::jsonb, 1, null, 'Subtract 4: 9x = 45. Divide by 9: x = 5.', 'published', 'import', now()),
('mathl1f_002', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If (x − 7)/2 = 6, what is the value of x?', null, null, '["19"]'::jsonb, 'Multiply by 2: x − 7 = 12, so x = 19.', 'published', 'import', now()),
('mathl1f_003', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 4x − 9 = x + 15, what is the value of x?', '["6", "8", "2", "24"]'::jsonb, 1, null, 'Subtract x and add 9: 3x = 24, so x = 8.', 'published', 'import', now()),
('mathl1f_004', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'Sam has $120 saved and adds $15 each week. After how many weeks will he have $300?', null, null, '["12"]'::jsonb, '120 + 15w = 300, so 15w = 180 and w = 12.', 'published', 'import', now()),
('mathl1f_005', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function h is defined by h(x) = 10 − 2x. What is h(3)?', '["7", "16", "4", "−4"]'::jsonb, 2, null, 'h(3) = 10 − 6 = 4.', 'published', 'import', now()),
('mathl1f_006', 'math', 1, 'Algebra', 'Linear functions', null, null, 'What is the slope of the line y = −4x + 9?', '["4", "9", "−9", "−4"]'::jsonb, 3, null, 'In y = mx + b, the slope is m = −4.', 'published', 'import', now()),
('mathl1f_007', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A plumber charges a $60 visit fee plus $45 for each hour of work. Which expression gives the total cost, in dollars, for h hours of work?', '["60h + 45h", "45 + 60h", "60 + 45h", "105h"]'::jsonb, 2, null, 'The $60 fee is charged once, and $45 is added for each hour.', 'published', 'import', now()),
('mathl1f_008', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'y = 3x
y = x + 8

What is the value of y?', null, null, '["12"]'::jsonb, 'Set them equal: 3x = x + 8, so x = 4 and y = 12.', 'published', 'import', now()),
